                        </h5>
                        <button v-on:click="ClosePopup($event)" type="button" class="close"
                            data-original-title="Close"><em class="fa fa-times"></em></button>
                    </div>
                    <div class="modal-body">

                        <div v-if="!isCommentAvailable" class="col-sm-12 col-md-12 col-lg-12 col-xl-12 px-0">

                            <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 px-0">
                                <dynamic-form lang="en" :buttons="buttons" ref="dynamicForm" :schema="FormSchema"
                                    :mandatorytext='MandatoryString' v-on:OnSubmit="onSubmit"></dynamic-form>

                            </div>
                        </div>
                        <!-- <div v-if="viewCommentData.length == 0" class="col-lg-12">
                            <div class="">
                                <div class="row">
                                    <div class="col-md-12 text-center text-danger  no_records">
                                        {{ $t('NoRecordfound') }}
                                    </div>
                                </div>
                            </div>
                        </div> -->

                        <div id="CommentsData" v-if="viewCommentData.length > 0" class="col-lg-12 mt-4"
                            style="max-height: 465px; overflow-y: auto;">
                            <div class="row">
                                <div class="col-lg-12 p-0">
                                    <div id="accordion" class="w-100 activity-tab">
                                        <div class="card">
                                            <div class="card-body">
                                                <div class="conversation-main" v-for="(item, index) in viewCommentData" :key="index">                                                    
                                                        <template v-if="item.comment != ''">
                                                            <div class="conversation-time">
                                                                <span>{{
                                                                    $options.filters.formatTimeFromDateTime(item.created_at)
                                                                    }}</span>
                                                            </div>
                                                            <div class="conversation-box-con">
                                                                <div class="conversation-box">
                                                                    <div class="name-circle">
                                                                        <img src="/Content/images/DefaultImages/avatar-icon.jpg"
                                                                            class="img-circle w-100 avatar" alt="Image">
                                                                    </div>
                                                                    <div class="conversation-header addednote-ticket">
                                                                        <span class="sender-department"
                                                                            style="margin-left:10px">
                                                                            <!-- <span class="sender-name"></span> -->
                                                                            <p>
                                                                                <span v-if="item.comment.length > 1"
                                                                                    id="more-49">
                                                                                    {{ item.comment }}
                                                                                    <br>
                                                                                </span>
                                                                                <span
                                                                                    v-else-if="item.comment.length < 49"
                                                                                    id="less-49" style="display: none">
                                                                                    <br>
                                                                                    <a class="font12 readLessLink comments editbtn pullleft"
                                                                                        value="49" href="javascript:;"
                                                                                        title="less">
