                                                                                    </a>
                                                                                </span>
                                                                            </p>
                                                                        </span>
                                                                    </div>

                                                                    <!-- <div class="conversation-content">
                                                                        <div class="col-12 p-0 notesdata">
                                                                            <h6 class="text-muted time"><i><b>
                                                                                        {{ $t('PRODUCT_NAME') }}:</b>
                                                                                    <span class="text-danger ml-2">{{
                                                                                        item.name }}</span>
                                                                                </i></h6>
                                                                        </div>
                                                                    </div>
                                                                    <div class="conversation-content">
                                                                        <div class="col-12 p-0 notesdata">
                                                                            <h6 class="text-muted time"><i><b>
                                                                                        {{ $t('UNIQUE_NAME') }}:</b>
                                                                                    <span class="text-danger ml-2">
                                                                                        {{ item.unique_name }}
                                                                                    </span>
                                                                                </i></h6>
                                                                        </div>
                                                                    </div>

                                                                    <div class="conversation-content">
                                                                        <div class="col-12 p-0 notesdata">
                                                                            <h6 class="text-muted time"><i><b>
                                                                                        {{ $t('Status') }}:</b> <span
                                                                                        class="text-danger ml-2">
                                                                                        {{
                                                                                            item.request_type ===
                                                                                                'ASSET_REPLACEMENT_APPROVED' ?
                                                                                                'Approved' :
                                                                                                item.request_type ===
                                                                                                    'ASSET_REPLACEMENT_REJECTED' ?
                                                                                                    'Rejected' :
                                                                                                    'Open'
                                                                                        }}
                                                                                    </span>
                                                                                </i></h6>
                                                                        </div>
                                                                    </div> -->

                                                                    <div class="conversation-content">
                                                                        <div class="col-12 p-0 notesdata">
                                                                            <h6 class="text-muted time"><i><b>{{
                                                                                item.created_by }}</b>,
                                                                                    {{ $t('PostedOn') }}: <span
                                                                                        class="text-danger" title="">{{
                                                                                            $options.filters.formatDate(item.created_at)
                                                                                        }} {{
                                                                                            toPrettyString(item.created_at)
                                                                                        }}</span>
                                                                                </i></h6>
                                                                        </div>
                                                                    </div>


                                                                </div>
                                                            </div>
                                                        </template>                                                    
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataService from '../../service/DataService';
export default {
    props: {
        ReplaceData: {
            type: Array,
            required: false,
        },
        AssetAssignmentId: {
            type: Number,
        },
        reqFrom: {
            type: String,
            required: false
        }
    },
    data() {

        return {
            MandatoryString: this.$t('MandatoryString'),
            isCommentAvailable: false,
            FormSchema: [

                {
                    layoutType: "triple",
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('ProductName'),
                            name: "ProductName",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        },
                        {
                            astype: "TextField",
                            label: this.$t('ItemName'),
                            name: "ItemName",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        },
                        {
                            astype: "TextField",
                            label: this.$t('Status'),
                            name: "Status",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        }
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",
                            label: this.$t('Comment'),
                            name: "Comment",
                            value: "",
                            placeholder: "",
                            validationRules: { "required": true },
                            visibility: true

                        }

                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Submit",
                    visibility: true
                },
                // {
                //     type: "button",
                //     class: "btn btn-danger",
                //     text: "<i class='fa fa-close pr-2'></i>Clear",
                //     onClick: this.onCancel,
                //     visibility: true
                // }

            ],

            viewCommentData: []

        }


    },
    created() {
        
        if (this.reqFrom == 'approvedlist') {
            this.FormSchema[1].Data[0].visibility = false
            this.buttons[0].isVisible = false;
        }
        this.getCommentDetails();
        this.FormSchema[0].Data[0].value = this.ReplaceData.NAME;
        this.FormSchema[0].Data[1].value = this.ReplaceData.UNIQUE_NAME;
        this.FormSchema[0].Data[2].value = this.ReplaceData.STATUS_NAME;

    },

    methods: {


        async getCommentDetails() {
            const vm = this;
            vm.isLoading = true;
            try {
                const url = `assetAssingmentId=${vm.AssetAssignmentId}&replacementId=${vm.ReplaceData.REPLACEMENT_ID}`;
                const response = await DataService.GetCommentDetails(url);
                if (!response?.data?.result) {
                    console.error('Invalid response structure:', response);
                    return;
                }
                const parsedResult = JSON.parse(response.data.result);
                const responseData = parsedResult?.data;
                if (!Array.isArray(responseData) || responseData.length === 0) {
                    vm.viewCommentData = [];
                    return;
                }
                vm.viewCommentData = responseData;
            } catch (error) {
                console.error('Error fetching comment details:', error);
            } finally {
                vm.isLoading = false;
            }
        },

        ClosePopup() {
            this.$parent.isShowComment = false;
        },
        onCancel() {
            this.FormSchema[1].Data[0].value = '';
        },

        onSubmit(formfields) {
            var vm = this;
            vm.isLoading = true;
            const obj = {
                assetAssignmentId: vm.AssetAssignmentId,
                comment: formfields.Comment,
                requestType: "MyProducts",
                replacementId:vm.ReplaceData.REPLACEMENT_ID
            }
            var JsonObj = `postString=${JSON.stringify(obj)}`;
            DataService.SaveAssetAssignMentCommentDetails(JsonObj).then(response => {
                if (response.data.result.Result == 1) {
                    vm.FormSchema[1].Data[0].value = '';
                    vm.$refs.dynamicForm.validateForm.reset();
                    vm.ShowAlert(vm.$t("CommentSuccess"), "success", vm.$t('Alert'));
                    vm.isLoading = false;
                    vm.getCommentDetails();
                } else {
                    vm.isLoading = false;

                }
            });


        }
        ,
        toPrettyString(userDate) {
            const now = new Date();
            const date = new Date(userDate);
            const ts = Math.abs(now - date); // Time difference in milliseconds
            const delta = ts / 1000; // Convert milliseconds to seconds

            if (delta < 60) {
                return 'few seconds ago';
            }
            if (delta < 120) {
                return 'a minute ago';
            }
            if (delta < 2700) { // 45 * 60
                return `${Math.floor(delta / 60)} minutes ago`;
            }
            if (delta < 5400) { // 90 * 60
                return 'an hour ago';
            }
            if (delta < 86400) { // 24 * 60 * 60
                return `${Math.floor(delta / 3600)} hours ago`;
            }
            if (delta < 172800) { // 48 * 60 * 60
                return 'yesterday';
            }
            if (delta < 2592000) { // 30 * 24 * 60 * 60
                return `${Math.floor(delta / 86400)} days ago`;
            }
            if (delta < 31104000) { // 12 * 30 * 24 * 60 * 60
                const months = Math.floor(delta / (30 * 86400));
                return months <= 1 ? '1 month ago' : `${months} months ago`;
            }
            const years = Math.floor(delta / (365 * 86400));
            return years <= 1 ? '1 year ago' : `${years} years ago`;
        },

    }

}
</script>
