<template>

    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">
                            {{ $t("ReplacyingRequest") }}: {{ ReplaceData.UNIQUE_NAME }}
                        </h5>
                        <button v-on:click="ClosePOP($event)" type="button" class="close"
                            data-original-title="Close"><em class="fa fa-times"></em></button>
                    </div>
                    <div class="border p-3">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema"
                            v-on:OnSubmit="onSubmit"></dynamic-form>
                    </div>

                    <div id="CommentsData" v-if="viewCommentData.length > 0" class="col-lg-12 mt-4"
                        style="max-height: 465px; overflow-y: auto;">
                        <div class="row">
                            <div class="col-lg-12">
                                <div id="accordion" class="w-100 activity-tab">
                                    <div class="card">
                                        <div class="card-body">
                                            <div class="conversation-main">
                                                <div v-for="(item, index) in viewCommentData" :key="index"
                                                    class="d-flex w-100 me-3">
                                                    <template v-if="item.comment != ''">
                                                        <div class="conversation-time">
                                                            <span>{{
                                                                $options.filters.formatTimeFromDateTime(item.created_at)
                                                            }}</span>
                                                        </div>
                                                        <div class="conversation-box-con">
                                                            <div class="conversation-box">
                                                                <div class="name-circle">
                                                                    <img src="/Content/images/DefaultImages/avatar-icon.jpg"
                                                                        class="img-circle w-100 avatar" alt="Image">
                                                                </div>
                                                                <div class="conversation-header addednote-ticket">
                                                                    <span class="sender-department"
                                                                        style="margin-left:10px">
                                                                        <span class="sender-name"></span>
                                                                        <p>
                                                                            <span v-if="item.comment.length > 1"
                                                                                id="more-49">
                                                                                {{ item.comment }}
                                                                                <br>
                                                                            </span>
                                                                            <span v-else-if="item.comment.length < 49"
                                                                                id="less-49" style="display: none">
                                                                                <br>
                                                                                <a class="font12 readLessLink comments editbtn pullleft"
                                                                                    value="49" href="javascript:;"
                                                                                    title="less">
                                                                                    less
                                                                                </a>
                                                                            </span>
                                                                        </p>
                                                                    </span>
                                                                </div>

                                                                <!-- <div class="conversation-content">
                                                                    <div class="col-12 p-0 notesdata">
                                                                        <h6 class="text-muted time"><i><b>
                                                                                    {{ $t('PRODUCT_NAME') }}:</b>
                                                                                <span class="text-danger"></span>
                                                                            </i></h6>
                                                                    </div>
                                                                </div>
                                                                <div class="conversation-content">
                                                                    <div class="col-12 p-0 notesdata">
                                                                        <h6 class="text-muted time"><i><b>
                                                                                    {{ $t('category_name') }}:</b>
                                                                                <span class="text-danger">

                                                                                </span>
                                                                            </i></h6>
                                                                    </div>
                                                                </div>

                                                                <div class="conversation-content">
                                                                    <div class="col-12 p-0 notesdata">
                                                                        <h6 class="text-muted time"><i><b>
                                                                                    {{ $t('Status') }}:</b> <span
                                                                                    class="text-danger">
                                                                                </span>
                                                                            </i></h6>
                                                                    </div>
                                                                </div> -->

                                                                <div class="conversation-content">
                                                                    <div class="col-12 p-0 notesdata">
                                                                        <h6 class="text-muted time"><i><b>{{
                                                                            item.created_by }}</b>,
                                                                                {{ $t('PostedOn') }}: <span
                                                                                    class="text-danger" title="">{{
                                                                                        $options.filters.formatDate(item.created_at)
                                                                                    }} {{ item.postedTime }}</span>
                                                                            </i></h6>
                                                                    </div>
                                                                </div>


                                                            </div>
                                                        </div>
                                                    </template>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>

</template>

<script>
import DataService from '../../service/DataService'
export default {
    props: {
        ReplaceData: {
            type: Array,
            required: true,
        },
        AssetAssignmentId: {
            type: Number,
        }
    },
    data() {
        return {
            FormSchema: [
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "SelectField",
                            label: this.$t("Status"),
                            name: "Status",
                            value: "ASSET_REPLACEMENT_APPROVED",
                            placeholder: "",
                            validationRules: { "required": false },
                            config: {
                                options: [
                                    { value: 'ASSET_REPLACEMENT_APPROVED', name: 'Approved' },
                                    { value: 'ASSET_REPLACEMENT_REJECTED', name: 'Rejected' },
                                    { value: 'Queried', name: 'Query' }
                                ],

                            },

                        },
                        {
                            astype: "TextAreaField",
                            label: this.$t('Remarks'),
                            name: "Remarks",
                            value: "",
                            validationRules: { "required": false, max: 1000 },
                            placeholder: "",
                            config: {
                                rows: 0
                            }
                        },
                    ]
                },
                {
                layoutType: "triple",
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('ProductName'),
                            name: "ProductName",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        },
                        {
                            astype: "TextField",
                            label: this.$t('ItemName'),
                            name: "ItemName",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        },
                        {
                            astype: "TextField",
                            label: this.$t('Status'),
                            name: "PrevStatus",
                            value: "",
                            placeholder: "",
                            disabled: true,
                            validationRules: { "required": true },

                        }
                    ]
                },

            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                },

                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.onCancel
                }
            ],
            viewCommentData:[],
            dataArray: [],
        }
    },
    created: function () {
        this.getCommentDetails();
        this.FormSchema[1].Data[0].value = this.ReplaceData.NAME;
        this.FormSchema[1].Data[1].value = this.ReplaceData.UNIQUE_NAME;    
        this.FormSchema[1].Data[2].value = this.ReplaceData.STATUS_NAME;
    },
    methods: {
        async getCommentDetails() {
            const vm = this;
            vm.isLoading = true;
            try {
                // const url = `assetAssingmentId=${vm.AssetAssignmentId}`;
                const url = `assetAssingmentId=${vm.AssetAssignmentId}&replacementId=${vm.ReplaceData.REPLACEMENT_ID}`;
                const response = await DataService.GetCommentDetails(url);
                if (!response?.data?.result) {
                    console.error('Invalid response structure:', response);
                    return;
                }
                const parsedResult = JSON.parse(response.data.result);
                const responseData = parsedResult?.data;
                if (!Array.isArray(responseData) || responseData.length === 0) {
                    vm.viewCommentData = [];
                    return;
                }
                vm.viewCommentData = responseData;
            } catch (error) {
                console.error('Error fetching comment details:', error);
            } finally {
                vm.isLoading = false;
            }
        },

        saveQuery(comment) {

            var vm = this;
            vm.isLoading = true;

            const obj = {
                assetAssignmentId: vm.AssetAssignmentId,
                comment: comment,
                requestType: "ReplaceRequest",
                status: "Queried",
                replacementId:vm.ReplaceData.REPLACEMENT_ID
            }
            var JsonObj = `postString=${JSON.stringify(obj)}`;
            DataService.SaveAssetAssignMentCommentDetails(JsonObj).then(response => {
                if (response.data.result.Result == 1) {
                    vm.ShowAlert(vm.$t("CommentSuccess"), "success", vm.$t('Alert'));
                    vm.isLoading = false;
                    vm.$parent.GetAssetReplacement();
                    vm.$parent.ClosePOP();
                // vm.getCommentDetails();
                } else {
                    vm.isLoading = false;
                }
            });

        },


        onSubmit: function (formfields) {
            var vm = this;
            //debugger
            if(formfields.Status == 'Queried'){

                vm.saveQuery(formfields.Remarks);
                return;
            }
            if(formfields.Status == ''){
                vm.ShowAlert(vm.$t("Please select status"), "failure", true, vm.$t('Alert'));
                return;
            }

            var obj = {                        
                        "Quantity": vm.ReplaceData.NUMBER_OF_ITEMS,                       
                        "UniqueName": this.ReplaceData.UNIQUE_NAME,
                        "CatalogName": this.ReplaceData.NAME
                    }
                    vm.dataArray.push(obj);

            vm.isLoading = true;
            const ReplaceData = {
                ReplacementID: vm.ReplaceData.REPLACEMENT_ID,
                ReplaceRequestStatus: formfields.Status,
                AssetCatalogueId: vm.ReplaceData.ASSET_CATALOGUE_ID,
                RelatedInfoId: vm.ReplaceData.RELATED_INFO_ID,
                NumberOfItems: vm.ReplaceData.NUMBER_OF_ITEMS,
                comment: formfields.Remarks,
                Userids: vm.ReplaceData.USER_ID,
                ProductName :this.ReplaceData.NAME,
                GroupRequistionAssestInfostring: vm.dataArray,
            }
            //debugger;      
            // vm.$refs.RejectForm.validate().then(result=>{ 
            // if(result){     
            // var url=`ReplacementID=${vm.ReplacesData.REPLACEMENT_ID}&ReplaceRequestStatus=${vm.OptionNames}&AssetCatalogueId=${vm.ReplacesData.ASSET_CATALOGUE_ID}&RelatedInfoId=${vm.ReplacesData.RELATED_INFO_ID}&NumberOfItems=${vm.ReplacesData.NUMBER_OF_ITEMS}&comment=${vm.Remarks}&Userids=${vm.ReplacesData.USER_ID}`;           
            DataService.SaveReplacementRequestStatus(ReplaceData).then(response => {
                if (response.data != null) {
                    //debugger

                    vm.ShowAlert(vm.$t(response.data), "success", vm.$t('Alert'));
                    vm.$parent.GetAssetReplacement();
                    vm.$parent.ClosePOP();
                }
                else {
                    vm.ShowAlert(vm.$t("Failed to Save"), "failure", true, vm.$t('Alert'));
                    vm.$parent.ClosePOP();
                }
                setTimeout(function () { vm.CheckBoxBootstrap() }, 100);
            });
            //}
            //})
        },

        onCancel: function (item) {
            this.ClosePOP(item);
        },
        ClosePOP: function (item) {

            this.$emit('ClosePOP', item);
        }
    }
}
</script>