                                    $options.filters.formatDateTimeMMDDYY(RejectData.FROM_TIME) }}</label></div>
                            </div>
                            <div class="col-md-6 col-lg-4">
                                <div class="form-group"><label><b>{{ $t("ToTime") }}:</b> {{
                                    $options.filters.formatDateTimeMMDDYY(RejectData.TO_TIME) }}</label></div>
                            </div>

                        </div>

